using System;
using System.Text.Json.Serialization;
using Asana.Core.Models;

namespace Asana.Models;

/// <summary>
/// An *event* is an object representing a change to a resource that was
/// observed by an event subscription or delivered asynchronously to
/// the target location of an active webhook.
/// <para>
/// The event may be triggered by a different <c>user</c> than the
/// subscriber. For example, if user A subscribes to a task and user B
/// modified it, the event’s user will be user B. Note: Some events
/// are generated by the system, and will have <c>null</c> as the user. API
/// consumers should make sure to handle this case.
/// </para>
/// <para>
/// The <c>resource</c> that triggered the event may be different from the one
/// that the events were requested for or the webhook is subscribed to. For
/// example, a subscription to a project will contain events for tasks
/// contained within the project.
/// </para>
/// <para>
/// <b>Note:</b> pay close attention to the relationship between the fields
/// <c>Event.action</c> and <c>Event.change.action</c>.
/// <c>Event.action</c> represents the action taken on the resource
/// itself, and <c>Event.change.action</c> represents how the information
/// within the resource's fields have been modified.
/// </para>
/// <para>
/// For instance, consider these scenarios:
/// </para>
/// <para>
///
/// * When at task is added to a project, <c>Event.action</c> will be
/// <c>added</c>, <c>Event.parent</c> will be an object with the <c>id</c> and
/// <c>type</c> of the project, and there will be no <c>change</c> field.
/// </para>
/// <para>
///
/// * When an assignee is set on the task, <c>Event.parent</c> will be
/// <c>null</c>, <c>Event.action</c> will be <c>changed</c>,
/// <c>Event.change.action</c> will be <c>changed</c>, and <c>new_value</c> will
/// be an object with the user's <c>id</c> and <c>type</c>.
/// </para>
/// <para>
///
/// * When a collaborator is added to the task, <c>Event.parent</c> will
/// be <c>null</c>, <c>Event.action</c> will be <c>changed</c>,
/// <c>Event.change.action</c> will be <c>added</c>, and <c>added_value</c> will be
/// an object with the user's <c>id</c> and <c>type</c>.
/// </para>
/// </summary>
public record EventResponse
{
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("user")]
    public UserCompact? User { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("resource")]
    public AsanaNamedResource? Resource { get; init; }

    /// <summary>
    /// *Deprecated: Refer to the resource_type of the resource.* The type of the resource that generated the event.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("type")]
    public string? Type { get; init; }

    /// <summary>
    /// The type of action taken on the <b>resource</b> that triggered the event.  This can be one of <c>changed</c>, <c>added</c>, <c>removed</c>, <c>deleted</c>, or <c>undeleted</c> depending on the nature of the event.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("action")]
    public string? Action { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("parent")]
    public AsanaNamedResource? Parent { get; init; }

    /// <summary>
    /// The timestamp when the event occurred.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("created_at")]
    public DateTimeOffset? CreatedAt { get; init; }

    /// <summary>
    /// Information about the type of change that has occurred. This field is only present when the value of the property <c>action</c>, describing the action taken on the <b>resource</b>, is <c>changed</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("change")]
    public Change? Change { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
